import React from 'react';
import styled from '@emotion/styled';
import { theme } from '@atlantis/shared';

export type IconButtonShape = 'square' | 'circle';

interface StyledIconBtnProps {
  active: boolean;
  shape: IconButtonShape;
  tone: 'default' | 'danger';
}

const TONE_HOVER_COLOR: Record<StyledIconBtnProps['tone'], string> = {
  default: theme.colors.accent,
  danger:  '#f85149',
};

const TONE_HOVER_BG: Record<StyledIconBtnProps['tone'], string> = {
  default: theme.colors.sidebarHover,
  danger:  'rgba(248,81,73,0.12)',
};

const StyledIconBtn = styled.button<StyledIconBtnProps>`
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 30px;
  height: 30px;
  padding: 0;
  background: ${({ active }) => (active ? `${theme.colors.accent}22` : 'transparent')};
  border: 1px solid
    ${({ active }) => (active ? theme.colors.accent : theme.colors.border)};
  border-radius: ${({ shape }) =>
    shape === 'circle' ? '999px' : theme.borderRadius.sm};
  color: ${({ active }) =>
    active ? theme.colors.accent : theme.colors.mainTextMuted};
  cursor: pointer;
  transition: background 0.15s, border-color 0.15s, color 0.15s;

  &:hover:not(:disabled) {
    color: ${({ tone }) => TONE_HOVER_COLOR[tone]};
    background: ${({ tone }) => TONE_HOVER_BG[tone]};
    border-color: ${({ tone }) => TONE_HOVER_COLOR[tone]};
  }
  &:focus-visible {
    outline: 2px solid ${theme.colors.accent};
    outline-offset: 2px;
  }
  &:disabled {
    opacity: 0.45;
    cursor: not-allowed;
  }
`;

export interface IconButtonProps
  extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  active?: boolean;
  shape?: IconButtonShape;
  tone?: 'default' | 'danger';
}

export const IconButton = React.forwardRef<HTMLButtonElement, IconButtonProps>(
  function IconButton(
    { active = false, shape = 'square', tone = 'default', children, ...rest },
    ref,
  ) {
    return (
      <StyledIconBtn ref={ref} active={active} shape={shape} tone={tone} {...rest}>
        {children}
      </StyledIconBtn>
    );
  },
);
