import React, { useState, useCallback } from 'react';
import styled from '@emotion/styled';
import { theme } from '../theme';
import { Layout } from './Layout';
import { NavTree } from './NavTree';
import type { NavEntry } from '../types';

interface DashboardLayoutProps {
  title: string;
  sections: NavEntry[];
  topBarRight?: React.ReactNode;
  children: React.ReactNode;
}

export function DashboardLayout({ title, sections, topBarRight, children }: DashboardLayoutProps) {
  const [activeSection, setActiveSection] = useState<string | null>(null);

  const handleSelect = useCallback((entry: NavEntry) => {
    setActiveSection(entry.id);
    document.getElementById(entry.id)?.scrollIntoView({ behavior: 'smooth', block: 'start' });
  }, []);

  const sidebar = (
    <NavTree entries={sections} activeId={activeSection} onSelect={handleSelect} />
  );

  return (
    <Layout title={title} sidebar={sidebar} activeId={activeSection} topBarRight={topBarRight}>
      {children}
    </Layout>
  );
}

export const DashContent = styled.div`
  padding: ${theme.spacing.xl};
  display: flex;
  flex-direction: column;
  gap: ${theme.spacing.xl};
  max-width: 1400px;
  width: 100%;
  min-width: 0;
  box-sizing: border-box;
`;

export const DashSection = styled.section`
  scroll-margin-top: ${theme.spacing.lg};
`;

export const DashPanel = styled.div`
  background: ${theme.colors.surface};
  border: 1px solid ${theme.colors.border};
  border-radius: ${theme.borderRadius.lg};
  padding: ${theme.spacing.lg};
`;

export const DashMidRow = styled.div`
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: ${theme.spacing.xl};

  @media (max-width: ${theme.breakpoints.lg}) {
    grid-template-columns: 1fr;
  }
`;
