import { useEffect, useState, useCallback } from 'react';
import { getSetting, putSetting } from './db';

export type Interest = 'tech' | 'movies' | 'learning' | 'games' | 'news' | 'space';
export type AgeMode = 'kid' | 'teen' | 'adult';

export interface UserProfile {
  interests: Interest[];
  ageMode: AgeMode;
}

const PROFILE_KEY = 'shell:profile';
const CHANGE_EVENT = 'atlantis:profile-change';

export const ALL_INTERESTS: Interest[] = ['tech', 'movies', 'learning', 'games', 'news', 'space'];

export const INTEREST_LABELS_EN: Record<Interest, string> = {
  tech: 'Tech',
  movies: 'Movies & TV',
  learning: 'Learning',
  games: 'Games',
  news: 'News',
  space: 'Space',
};

export const INTEREST_LABELS_PT: Record<Interest, string> = {
  tech: 'Tecnologia',
  movies: 'Filmes & Séries',
  learning: 'Aprender',
  games: 'Jogos',
  news: 'Notícias',
  space: 'Espaço',
};

export const AGE_MODE_LABELS_EN: Record<AgeMode, string> = {
  kid: 'Kid',
  teen: 'Teen',
  adult: 'Adult',
};

export const AGE_MODE_LABELS_PT: Record<AgeMode, string> = {
  kid: 'Criança',
  teen: 'Adolescente',
  adult: 'Adulto',
};

export const DEFAULT_PROFILE: UserProfile = {
  interests: [],
  ageMode: 'adult',
};

function normalize(raw: unknown): UserProfile {
  if (!raw || typeof raw !== 'object') return DEFAULT_PROFILE;
  const r = raw as Partial<UserProfile>;
  const interests = Array.isArray(r.interests)
    ? r.interests.filter((i): i is Interest => ALL_INTERESTS.includes(i as Interest))
    : [];
  const ageMode: AgeMode =
    r.ageMode === 'kid' || r.ageMode === 'teen' || r.ageMode === 'adult' ? r.ageMode : 'adult';
  return { interests, ageMode };
}

/**
 * Reactive profile hook. Persists to `shell:profile` via shared storage (IDB → Supabase).
 * Emits `atlantis:profile-change` so all mounted consumers update together.
 */
export function useProfile(): [UserProfile, (next: UserProfile) => void] {
  const [profile, setProfile] = useState<UserProfile>(DEFAULT_PROFILE);

  useEffect(() => {
    let cancelled = false;
    getSetting(PROFILE_KEY).then((raw) => {
      if (cancelled || !raw) return;
      try { setProfile(normalize(JSON.parse(raw))); }
      catch { /* ignore — keep default */ }
    });
    const onChange = (e: Event) => {
      const detail = (e as CustomEvent<UserProfile>).detail;
      if (detail) setProfile(detail);
    };
    window.addEventListener(CHANGE_EVENT, onChange);
    return () => {
      cancelled = true;
      window.removeEventListener(CHANGE_EVENT, onChange);
    };
  }, []);

  const update = useCallback((next: UserProfile) => {
    const normalized = normalize(next);
    setProfile(normalized);
    putSetting(PROFILE_KEY, JSON.stringify(normalized));
    window.dispatchEvent(new CustomEvent(CHANGE_EVENT, { detail: normalized }));
  }, []);

  return [profile, update];
}

/** Returns true if any interest is selected — useful for "apply filters only when set". */
export function hasInterests(profile: UserProfile): boolean {
  return profile.interests.length > 0;
}

/**
 * Keyword patterns for each `Interest`. Used by `detectInterests()` to catch
 * off-topic items that slip through a row's static interest tag. Patterns are
 * bilingual (EN + PT); add more keywords if you see a false negative.
 *
 * Scoped narrowly on purpose — each keyword should be unambiguous. "war"
 * matches news, "movie" matches movies, etc. Common English words that have
 * many meanings (e.g. "ball") don't belong here.
 */
export const INTEREST_KEYWORDS: Record<Interest, RegExp> = {
  space: /\b(NASA|Kepler|Hubble|SpaceX|JWST|James Webb|astronaut[ae]?|astronomia?|telesc[oó]pio|telescope|planet(a|s)?|galax(y|ia)|gal[aá]xia|espa[cç]o|cosmos|foguet[ãa]o|Marte|Saturn[oa]?|J[úu]piter|[oó]rbita|orbit|black ?hole|buraco negro)\b/i,
  tech: /\b(GitHub|JavaScript|TypeScript|Python|Rust|LLM|ChatGPT|OpenAI|algoritmos?|algorithms?|developer|programador|c[oó]digo fonte|source code|compiler|compilador|framework)\b/i,
  movies: /\b(film(e|es)?|movie|cinema|Oscar|Netflix|streaming|trailer|s[eé]rie|episode|epis[oó]dio|director|realizador)\b/i,
  games: /\b(gaming|videojogo|videogame|Nintendo|PlayStation|Xbox|speedrun|e-sports?|DLC|Twitch)\b/i,
  news: /\b(elei[cç][õã]o|election|guerra|war|crise|crisis|ministr[oa]|president(e|a)?|government|governo|parlamento|parliament)\b/i,
  learning: /\b(escola|school|matem[aá]tica|math(s|ematics)?|professor(a)?|teacher|aluno|student|pedagog|curriculum|curr[ií]culo)\b/i,
};

/**
 * Scan free text (title + subtitle, etc.) for interest-indicating keywords.
 * Returns every `Interest` whose keyword pattern matched. Useful for enforcing
 * preferences on content whose static tag may not capture the real topic —
 * e.g. an "On This Day" entry tagged `learning` but actually about NASA.
 */
export function detectInterests(text: string): Interest[] {
  return (Object.keys(INTEREST_KEYWORDS) as Interest[])
    .filter((i) => INTEREST_KEYWORDS[i].test(text));
}

/** Numeric rank so `kid < teen < adult`. Use for age-gate comparisons. */
export const AGE_MODE_RANK: Record<AgeMode, number> = { kid: 0, teen: 1, adult: 2 };

/**
 * Returns true if a content item tagged with `minAgeMode` should be visible
 * to a user in the current `profile.ageMode`. Items without `minAgeMode`
 * default to `'kid'` — i.e. visible to everyone.
 */
export function allowedByAge(profile: UserProfile, minAgeMode?: AgeMode): boolean {
  return AGE_MODE_RANK[profile.ageMode] >= AGE_MODE_RANK[minAgeMode ?? 'kid'];
}

// ─── Media filtering by age ──────────────────────────────────────────────────
//
// TMDB genre IDs. The Family genre (10751) is the strong "kid-appropriate"
// signal — studios attach it to content aimed at kids. Animation alone (16)
// is NOT a reliable signal: Rick and Morty, South Park, adult animated shorts
// ("Le Clitoris") are all tagged Animation but have no Family tag.

/** TMDB's Family genre id — single required tag for the kid filter. */
export const KID_REQUIRED_GENRE_ID = 10751;

/** Legacy alias — prefer `KID_REQUIRED_GENRE_ID`. */
export const KID_FRIENDLY_GENRE_IDS: ReadonlySet<number> = new Set([KID_REQUIRED_GENRE_ID]);

/** Genres stripped for `teen` viewers on top of the adult-flag.
 *  - 27  Horror
 *  - 10770 TV Movie (not useful and often low-quality adult content)
 *  (Mature animated content still escapes; consider adding a runtime /
 *  certification check if a teen reports seeing something inappropriate.)
 */
export const TEEN_BLOCKED_GENRE_IDS: ReadonlySet<number> = new Set([27]);

/** Minimal shape for anything that can be filtered by age — TMDB MediaItem etc. */
export interface AgeFilterable {
  adult?: boolean;
  genre_ids?: number[];
}

/**
 * Age-adjust a list of media items. Pure function — pass in `ageMode`.
 *
 *  - `adult` → returns items unchanged.
 *  - `teen`  → drops items flagged `adult === true` AND items whose genres
 *              include any of `TEEN_BLOCKED_GENRE_IDS` (Horror).
 *  - `kid`   → drops adult AND keeps only items tagged with TMDB's Family
 *              genre (10751). Animation alone is intentionally not enough —
 *              it lets through adult/edgy animated content.
 *
 * Used by the Movies app (`apps/movies/src/tmdb.ts`) and the shell's
 * `MoviesWidget`; add new consumers here rather than re-implementing.
 */
export function filterMediaByAge<T extends AgeFilterable>(items: T[], ageMode: AgeMode): T[] {
  if (ageMode === 'adult') return items;
  const nonAdult = items.filter((i) => i.adult !== true);
  if (ageMode === 'teen') {
    return nonAdult.filter(
      (i) => !(i.genre_ids ?? []).some((g) => TEEN_BLOCKED_GENRE_IDS.has(g)),
    );
  }
  return nonAdult.filter(
    (i) => (i.genre_ids ?? []).includes(KID_REQUIRED_GENRE_ID),
  );
}
